//! Process subscriber policy and the sole HTTP completion event owner.

use std::time::Duration;

use axum::{
    Router,
    body::Body,
    extract::{MatchedPath, Request},
    middleware::{self, Next},
    response::Response,
};
use tower::{Layer, ServiceExt, service_fn};
use tower_http::trace::TraceLayer;
use tracing::{Level, Span};
use tracing_subscriber::EnvFilter;

use super::error::ResponseFailure;

pub(super) fn init_subscriber() -> anyhow::Result<()> {
    let directives = match std::env::var("RUST_LOG") {
        Ok(value) => value,
        Err(std::env::VarError::NotPresent) => "warn,exposed=info".into(),
        Err(error) => return Err(error.into()),
    };
    let filter = EnvFilter::builder()
        .with_regex(false)
        .parse(directives)?;
    tracing_subscriber::fmt()
        .json()
        .with_env_filter(filter)
        .with_writer(std::io::stderr)
        .try_init()
        .map_err(|error| anyhow::anyhow!(error))
}

pub(super) fn instrument<S>(router: Router<S>) -> Router<S>
where
    S: Clone + Send + Sync + 'static,
{
    router.layer(middleware::from_fn(trace_request))
}

async fn trace_request(request: Request, next: Next) -> Response {
    let method = request.method().clone();
    let route = request.extensions().get::<MatchedPath>().cloned();
    let health = route.as_ref().is_some_and(|path| path.as_str() == "/healthz");
    let span_method = method.clone();
    let span_route = route.clone();
    // Capture request identity outside the span so filtered health spans still
    // leave method and route available to a failed response's completion event.
    let layer = TraceLayer::new_for_http()
        .make_span_with(move |_: &Request| {
            let route = span_route.as_ref().map(MatchedPath::as_str);
            if health {
                tracing::span!(Level::DEBUG, "http.request",
                    http.request.method = %span_method, http.route = route)
            } else {
                tracing::span!(Level::INFO, "http.request",
                    http.request.method = %span_method, http.route = route)
            }
        })
        .on_request(())
        .on_response(move |response: &Response, latency: Duration, _: &Span| {
            complete(response, latency, &method, route.as_ref(), health);
        })
        .on_body_chunk(())
        .on_eos(())
        .on_failure(());
    let service = layer.layer(service_fn(move |request: Request<Body>| {
        let next = next.clone();
        async move { Ok::<_, std::convert::Infallible>(next.run(request).await) }
    }));
    match service.oneshot(request).await {
        Ok(response) => response,
        Err(never) => match never {},
    }
}

#[allow(clippy::disallowed_macros, reason = "sole HTTP response completion emitter")]
fn complete(
    response: &Response,
    latency: Duration,
    method: &axum::http::Method,
    route: Option<&MatchedPath>,
    health: bool,
) {
    let status = response.status();
    let category = response.extensions().get::<ResponseFailure>()
        .map(ResponseFailure::category)
        .or_else(|| {
            if status.is_server_error() { Some("http.server_error") }
            else if status.is_client_error() { Some("http.client_error") }
            else { None }
        });
    let route = route.map(MatchedPath::as_str);
    macro_rules! emit {
        ($level:expr) => {
            tracing::event!(
                $level,
                name = "http.request.completed",
                http.request.method = %method,
                http.route = route,
                http.response.status_code = u64::from(status.as_u16()),
                duration_ms = latency.as_secs_f64() * 1000.0,
                error.type = category,
            )
        };
    }
    if status.is_server_error() { emit!(Level::ERROR); }
    else if status.is_client_error() { emit!(Level::WARN); }
    else if health { emit!(Level::DEBUG); }
    else { emit!(Level::INFO); }
}
